// ════════════════════════════════════════════════════════════════════════════
// /api/og.tsx — Dynamic Open Graph image for FARMASI rep landing pages
// Runtime: Vercel Edge
// Returns: 1200x630 PNG personalized with rep's photo + name + city + logo
// Layout: photo left, name center, logo top-right corner
// ════════════════════════════════════════════════════════════════════════════

import { ImageResponse } from '@vercel/og';

export const config = { runtime: 'edge' };

const APPS_SCRIPT_URL =
  'https://script.google.com/macros/s/AKfycby0BJOvqZZz4eK5zHyep36R3vcPvweNk8ob-sOcCEokNoGto9m1BrfBxNlBcBB81pJ5/exec';

const FONT_URL =
  'https://cdn.jsdelivr.net/npm/@fontsource/noto-serif-georgian@5.1.0/files/noto-serif-georgian-georgian-700-normal.woff';

let fontDataCache: ArrayBuffer | null = null;
async function getFont(): Promise<ArrayBuffer> {
  if (!fontDataCache) {
    const res = await fetch(FONT_URL);
    if (!res.ok) throw new Error('Font fetch failed: ' + res.status);
    fontDataCache = await res.arrayBuffer();
  }
  return fontDataCache;
}

// FARMASI logo embedded inline as base64 (processed from 4K source).
const LOGO_DATA_URL = 'data:image/png;base64,';

async function fetchRep(
  action: string,
  params: Record<string, string>
): Promise<any | null> {
  try {
    const q = new URLSearchParams({ ...params, action, callback: 'cb' }).toString();
    const res = await fetch(`${APPS_SCRIPT_URL}?${q}`);
    if (!res.ok) return null;
    const text = await res.text();
    const match = text.match(/^[^(]*\(([\s\S]*?)\)\s*;?\s*$/);
    if (!match) {
      try {
        const data = JSON.parse(text);
        return data.ok ? data.rep : null;
      } catch {
        return null;
      }
    }
    const data = JSON.parse(match[1]);
    return data.ok ? data.rep : null;
  } catch {
    return null;
  }
}

export default async function handler(req: Request) {
  const { searchParams } = new URL(req.url);
  const pid = searchParams.get('pid');
  const slug = searchParams.get('slug');

  const [rep, font] = await Promise.all([
    pid
      ? fetchRep('get_rep', { pid })
      : slug
      ? fetchRep('get_rep_by_slug', { slug })
      : Promise.resolve(null),
    getFont(),
  ]);

  const name = (rep?.name as string) || 'FARMASI';
  const city = (rep?.city as string) || '';
  const photoUrl = (rep?.photo_url as string) || '';
  const photo = /^https?:\/\//i.test(photoUrl) ? photoUrl : '';

  return new ImageResponse(
    (
      <div
        style={{
          width: '100%',
          height: '100%',
          display: 'flex',
          background:
            'linear-gradient(135deg, #FCE7F3 0%, #FFFFFF 50%, #FCE7F3 100%)',
          padding: 80,
          alignItems: 'center',
          gap: 60,
          fontFamily: 'Noto Serif Georgian',
          position: 'relative',
        }}
      >
        {/* Pink frame outline */}
        <div
          style={{
            position: 'absolute',
            top: 40,
            left: 40,
            right: 40,
            bottom: 40,
            border: '1px solid #BE185D',
            opacity: 0.15,
            display: 'flex',
          }}
        />

        {/* FARMASI logo — top-right corner badge */}
        <div
          style={{
            position: 'absolute',
            top: 60,
            right: 90,
            display: 'flex',
          }}
        >
          <img
            src={LOGO_DATA_URL}
            width={140}
            height={60}
            style={{ objectFit: 'contain' }}
          />
        </div>

        {/* LEFT — rep photo or branded fallback panel */}
        {photo ? (
          <img
            src={photo}
            width={420}
            height={460}
            style={{
              objectFit: 'cover',
              borderRadius: 12,
              border: '5px solid #E50571',
              boxShadow: '0 20px 60px rgba(229, 5, 113, 0.3)',
            }}
          />
        ) : (
          <div
            style={{
              width: 420,
              height: 460,
              background: '#FCE7F3',
              borderRadius: 12,
              border: '5px solid #E50571',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              padding: 60,
            }}
          >
            <img src={LOGO_DATA_URL} width={260} height={110} style={{ objectFit: 'contain' }} />
          </div>
        )}

        {/* RIGHT — name + tagline + city */}
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            flex: 1,
            gap: 14,
            marginTop: 60,
          }}
        >
          <div
            style={{
              fontSize: name.length > 14 ? 70 : 90,
              color: '#0F0F0F',
              fontWeight: 700,
              lineHeight: 1.05,
              letterSpacing: -2,
            }}
          >
            {name}
          </div>

          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 16,
              marginTop: 16,
            }}
          >
            <div style={{ width: 80, height: 3, background: '#E50571', display: 'flex' }} />
            <div style={{ fontSize: 34, color: '#E50571' }}>
              ნამდვილი ქალისთვის
            </div>
          </div>

          {city && (
            <div style={{ fontSize: 26, color: '#666', marginTop: 24, display: 'flex' }}>
              📍 {city}
            </div>
          )}
        </div>
      </div>
    ),
    {
      width: 1200,
      height: 630,
      fonts: [
        {
          name: 'Noto Serif Georgian',
          data: font,
          style: 'normal',
          weight: 700,
        },
      ],
      headers: {
        'Cache-Control':
          'public, max-age=3600, s-maxage=300, stale-while-revalidate=86400',
      },
    }
  );
}
